/* =========================================================================
 * 落第骑士英雄谭 · 破军伐刀者智能终端 v1.2.1 MONO ADV
 * 运行环境：TavernHelper 卡内脚本（script iframe）；UI 注入 ST 宿主 document
 * 结构：破军战术微光悬浮球(自由吸附) + 桌面浮动可拖拽终端(自由停靠与缩放) + 沙箱 iframe + MVU桥接
 * v1.2.1 更新：
 *   ① 添加輪盤展開動畫（scale + fade in）
 *   ② 終端打開時自動隱藏輪盤入口球
 *   ③ 移除硬編碼測試數據，使用 MVU 動態綁定
 *   ④ 模塊化開發結構，便於維護和擴展
 * ========================================================================= */
(async function () {
  'use strict';

  /* ==================== 核心模块 ==================== */
  /* =========================================================================
 * 落第骑士英雄谭 · 破军伐刀者智能终端 v1.3.0 MONO ADV
 * 运行环境：TavernHelper 卡内脚本（script iframe）；UI 注入 ST 宿主 document
 * 结构：破军战术微光悬浮球(自由吸附) + 桌面浮动可拖拽终端(自由停靠与缩放) + 沙箱 iframe + MVU桥接
 * v1.3.0 更新：模块化重构，支持源码维护和打包
 * ========================================================================= */
(async function () {
  'use strict';

  function hostWindow() {
    try { if (window.parent && window.parent !== window && window.parent.document) return window.parent; }
    catch (_) {}
    return window;
  }
  const HW = hostWindow();
  const HD = (function(){ try { return HW.document; } catch (_) { return document; } })();

  const SLOT = '__RK_PHONE_SHELL__';
  try { HW[SLOT] && HW[SLOT].destroy && HW[SLOT].destroy(); } catch (_) {}

  const SS = {
    mode: 'floating', visible: false,
    host: null, iframe: null, blobUrl: null, orb: null, style: null,
    rect: null, orbPos: {x: 0, y: 0},
    disposers: [], booted: false, mounting: null, destroyed: false, badge: 0,
    wheel: null, wheelBackdrop: null, wheelOpen: false, focusBeforeWheel: null
  };

  const LS = {
    get(k, d) { try { const v = HW.localStorage.getItem(k); return v == null ? d : JSON.parse(v); } catch(_) { return d; } },
    set(k, v) { try { HW.localStorage.setItem(k, JSON.stringify(v)); } catch(_) {} }
  };

  function fn(name) {
    try { if (typeof window[name] === 'function') return window[name]; } catch(_) {}
    try { if (window.TavernHelper && typeof window.TavernHelper[name] === 'function')
      return window.TavernHelper[name].bind(window.TavernHelper); } catch(_) {}
    return null;
  }

  const ORB_W = 68, ORB_H = 68;

  // 导入样式模块
  /*__INJECT_STYLES__*/

  // 导入布局和定位模块
  /*__INJECT_LAYOUT__*/

  // 导入轮盘模块
  /*__INJECT_WHEEL__*/

  // 导入终端窗口模块
  /*__INJECT_TERMINAL__*/

  // 导入嵌入式应用页面
  /*__INJECT_APP_HTML__*/

  // 初始化
  async function init() {
    buildDom();
    bindEvents();

    const autoShow = LS.get('rk:autoShow', false);
    if (autoShow) await show();
  }

  // 启动
  init().catch(e => console.error('[Hagun-Mono-Terminal] Init failed:', e));

  // 清理函数
  function destroy() {
    if (SS.destroyed) return;
    SS.destroyed = true;
    try {
      SS.disposers.forEach(d => d());
      if (SS.blobUrl) URL.revokeObjectURL(SS.blobUrl);
      [SS.style, SS.orb, SS.host, SS.wheel, SS.wheelBackdrop].forEach(el => el && el.remove());
      delete HW[SLOT];
    } catch(e) { console.warn('[Hagun-Mono-Terminal] Cleanup:', e); }
  }

  HW[SLOT] = { show, hide, toggle, destroy, recenter, version: '1.3.0' };
})();

  /* ==================== 样式定义 ==================== */
  const css = `#rk-orb,#rk-shell,#rk-wheel,#rk-wheel-curtain{box-sizing:border-box;font-family:"Microsoft YaHei UI","Noto Sans CJK SC",sans-serif;font-weight:400;font-size:14px;line-height:1.4;text-shadow:none;letter-spacing:normal;}#rk-shell *,#rk-wheel *{box-sizing:border-box;}#rk-orb{position:fixed;z-index:99990;width:68px;height:68px;padding:3px;background:#080808;color:#fff;border:9px solid transparent;border-image:url("data:image/svg+xml;base64,") 16 stretch;display:flex;align-items:center;justify-content:center;cursor:pointer;user-select:none;touch-action:none;border-radius:0;box-shadow:3px 3px 0 #080808;outline:none;transition:opacity 0.2s ease;}#rk-orb .crest{display:flex;flex-direction:column;align-items:center;gap:1px;line-height:1.15;pointer-events:none;}#rk-orb .crest svg{display:block;width:27px;height:27px;}#rk-orb .crest span{font-family:"Noto Serif CJK SC","Songti SC","SimSun",serif;font-size:12px;letter-spacing:2px;white-space:nowrap;}#rk-orb:hover .crest,#rk-orb:focus-visible .crest{opacity:0.72;}#rk-orb:focus-visible{outline:2px solid #fff;outline-offset:4px;}#rk-orb[aria-expanded="true"],#rk-shell.on ~ #rk-orb{visibility:hidden;pointer-events:none;}#rk-shell{position:fixed;z-index:99991;background:#080808;color:#fff;border:12px solid transparent;border-image:url("data:image/svg+xml;base64,") 16 stretch;border-radius:0;box-shadow:6px 6px 0 rgba(0,0,0,0.65);display:none;flex-direction:column;overflow:hidden;isolation:isolate;}#rk-shell.on{display:flex;}#rk-wheel-curtain{position:fixed;display:none;z-index:99992;background:rgba(0,0,0,0.16);touch-action:none;}#rk-wheel-curtain.on{display:block;}#rk-wheel{position:fixed;z-index:99993;display:none;user-select:none;touch-action:manipulation;color:#fff;pointer-events:none;filter:drop-shadow(3px 4px 0 rgba(0,0,0,0.6));background:transparent;}#rk-wheel.on{display:block;animation:rk-wheel-open 0.25s cubic-bezier(0.68,-0.55,0.27,1.55);}@keyframes rk-wheel-open{from{opacity:0;transform:scale(0.7) rotate(-10deg);}to{opacity:1;transform:scale(1) rotate(0deg);}}@media (prefers-reduced-motion:reduce){#rk-wheel.on{animation:rk-wheel-open-simple 0.15s ease-out;}@keyframes rk-wheel-open-simple{from{opacity:0;}to{opacity:1;}}}#rk-wheel .mono-wheel-svg{pointer-events:none;}#rk-wheel .mono-sector,#rk-wheel .mono-core,#rk-wheel .mono-wheel-close{pointer-events:auto;}#rk-wheel .mono-sector{cursor:pointer;outline:none;--sector-ink:#fff;--sector-bg:#080808;transition:all 0.15s ease;}#rk-wheel .mono-sector:is(:hover,:focus-visible){--sector-ink:#080808;--sector-bg:#fff;}#rk-wheel .mono-sector:active .mono-sector-shape{fill:#cfcfcf;}`;

  /* ==================== 輪盤模块 ==================== */
  /* =========================================================================
 * 轮盘组件 - 八方应用选择器
 * ========================================================================= */

const RADIAL_APPS = ['blazer', 'lime', 'moments', 'bbs', 'schedule', 'gallery', 'worldbook', 'settings'];

/**
 * 放置轮盘到合适的位置
 */
function placeWheel(SS, HW) {
  if (!SS.wheel || !SS.wheelOpen) return;

  const vp = viewport(HW);
  const size = Math.min(370, vp.w - 20, vp.h - 72);
  const cx = SS.orbPos.x + 68 / 2;
  const cy = SS.orbPos.y + 68 / 2;
  const x = Math.max(vp.x + 10, Math.min(cx - size / 2, vp.x + vp.w - size - 10));
  const y = Math.max(vp.y + 10, Math.min(cy - size / 2, vp.y + vp.h - size - 56));

  writePos(SS.wheel, x, y, size, size, HW);
  writePos(SS.wheelBackdrop, vp.x, vp.y, vp.w, vp.h, HW);
}

/**
 * 关闭轮盘
 */
function closeWheel(SS, restoreFocus) {
  if (!SS.wheelOpen) return;

  SS.wheelOpen = false;
  SS.wheel.classList.remove('on');
  SS.wheelBackdrop.classList.remove('on');
  SS.orb.setAttribute('aria-expanded', 'false');

  if (restoreFocus) {
    const target = SS.focusBeforeWheel && SS.focusBeforeWheel.isConnected 
      ? SS.focusBeforeWheel 
      : SS.orb;
    try { 
      target.focus({ preventScroll: true }); 
    } catch (_) {}
  }
}

/**
 * 切换轮盘显示
 */
function toggleWheel(SS, keyboard, HW, HD) {
  if (SS.destroyed) return;

  if (SS.wheelOpen) {
    closeWheel(SS, true);
    return;
  }

  clearOrbTip(SS);
  SS.focusBeforeWheel = HD.activeElement;
  SS.wheelOpen = true;
  SS.wheel.classList.add('on');
  SS.wheelBackdrop.classList.add('on');
  SS.orb.setAttribute('aria-expanded', 'true');
  SS.wheel.querySelector('.mono-wheel-caption b').textContent = '选择终端应用';

  placeWheel(SS, HW);

  if (keyboard) {
    SS.wheel.querySelector('.mono-sector').focus();
  }
}

/**
 * 打开终端应用
 */
async function openPhoneApp(SS, appId, show) {
  if (appId !== 'home' && !RADIAL_APPS.includes(appId)) return;

  closeWheel(SS, false);
  await show();

  if (!SS.visible || !SS.booted || SS.destroyed) return;

  try {
    const iw = SS.iframe && SS.iframe.contentWindow;
    if (!iw) return;

    if (typeof iw.goHome === 'function') {
      iw.goHome();
    }

    if (appId !== 'home' && typeof iw.openApp === 'function') {
      iw.openApp(appId);
    }

    iw.focus();
  } catch (e) {
    console.warn('[Hagun-Mono-Terminal] Navigation:', e);
  }
}

/**
 * 构建轮盘 DOM
 */
function buildWheel(SS, HD, HW, show) {
  // 创建背景遮罩
  SS.wheelBackdrop = HD.createElement('div');
  SS.wheelBackdrop.id = 'rk-wheel-curtain';
  SS.wheelBackdrop.setAttribute('aria-hidden', 'true');
  HD.body.appendChild(SS.wheelBackdrop);

  // 创建轮盘
  SS.wheel = HD.createElement('div');
  SS.wheel.id = 'rk-wheel';
  SS.wheel.setAttribute('aria-label', '破军终端操作轮盘');
  SS.wheel.innerHTML = getWheelHTML();
  HD.body.appendChild(SS.wheel);

  // 绑定轮盘事件
  bindWheelEvents(SS, HD, HW, show);

  // 绑定遮罩点击关闭
  SS.wheelBackdrop.addEventListener('click', () => closeWheel(SS, true));
}


if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    placeWheel,
    closeWheel,
    toggleWheel,
    openPhoneApp,
    buildWheel,
    RADIAL_APPS
  };
}

  /* ==================== 内嵌应用 HTML ==================== */
  const terminalAppHTMLBase64 = '';

})();
